insert into project_tech_topics (tech_topic_id, project_id, block_kind, title, summary, body_md, tech_domain, sort_order, status, confidentiality, source_kind, source_ref, source_url, needs_check, check_reason, created_by, updated_by) values ($t$ptt_sx_comp_galdieria$t$, $t$p21$t$, $t$article$t$, $t$ガルデリアとの違い — 聞かれたときの答え方つき$t$, $t$微生物の金属回収で最初に名前が出る相手。何をしている会社か、SXと同じところ・違うところ、答え方。2026-09-14 に公開情報で確認。$t$, $t$**一言でいうと** — 温泉にすむ紅藻ガルディエリアを乾かして吸着剤にし、強い酸性のごく薄い液から金・パラジウムを取る会社。2026年6月に、めっき工場でパラジウム回収を商用導入した。8月には、生きた藻に工場排水の有機物を食べさせる取り組みもリバネスと始めている。
insert into project_tech_topics (tech_topic_id, project_id, block_kind, title, summary, body_md, tech_domain, sort_order, status, confidentiality, source_kind, source_ref, source_url, needs_check, check_reason, created_by, updated_by) values ($t$ptt_sx_comp_qa$t$, $t$p21$t$, $t$article$t$, $t$よく聞かれる問いと答え方 — 投資家・事業会社向け$t$, $t$聞かれやすい7つの問いに、答え方の例・根拠のトピック・言わないほうがいいことを置く。答え方は事業概要 v1.7 の書き方と、この区分の事実に沿わせている。$t$, $t$答え方は例。数字は、根拠のトピックとコスト試算タブで最新を確かめてから使う。
